<?php

namespace App\Rules;

use Closure;
use Illuminate\Contracts\Validation\ValidationRule;

class SecretEnvironmentKey implements ValidationRule
{
    /**
     * Variables the wrapper itself controls. A project secret must never
     * override the execution environment generated by the runner.
     */
    public const RESERVED = [
        'APP_DIR',
        'CI',
        'EXPO_NO_TELEMETRY',
        'PATH',
        'PATHEXT',
        'PSMODULEPATH',
        'SYSTEMROOT',
        'WINDIR',
        'COMSPEC',
        'TEMP',
        'TMP',
        'USERPROFILE',
        'APPDATA',
        'LOCALAPPDATA',
        'PROGRAMDATA',
        'PROGRAMFILES',
        'HOMEDRIVE',
        'HOMEPATH',
        'HOME',
        'JAVA_HOME',
        'ANDROID_HOME',
        'ANDROID_SDK_ROOT',
        'NODE_ENV',
    ];

    public function validate(string $attribute, mixed $value, Closure $fail): void
    {
        if (! is_string($value) || preg_match('/^[A-Za-z_][A-Za-z0-9_]{0,119}$/', $value) !== 1) {
            $fail('A chave deve começar com letra ou "_" e conter apenas letras, números e "_".');

            return;
        }

        $normalized = strtoupper($value);

        if (str_starts_with($normalized, 'BUILD_') || in_array($normalized, self::RESERVED, true)) {
            $fail('Esta chave é reservada pelo runner e não pode ser usada como segredo.');
        }
    }
}
